import{_ as i,c as a,o as r,aj as t,aD as e,aE as o,aF as n}from"./chunks/framework.8bp-HAn5.js";const b=JSON.parse('{"title":"输出节点","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"node-output.md","filePath":"node-output.md"}'),s={name:"node-output.md"};function p(h,l,u,g,d,c){return r(),a("div",null,[...l[0]||(l[0]=[t('<h1 id="输出节点" tabindex="-1">输出节点 <a class="header-anchor" href="#输出节点" aria-label="Permalink to “输出节点”">​</a></h1><h2 id="提示" tabindex="-1">提示 <a class="header-anchor" href="#提示" aria-label="Permalink to “提示”">​</a></h2><h3 id="文字提示" tabindex="-1">文字提示 <a class="header-anchor" href="#文字提示" aria-label="Permalink to “文字提示”">​</a></h3><p>弹出文字提示信息，显示给用户。</p><p><strong>输入：</strong></p><ul><li>msg：要显示的提示内容（可通过属性设置）</li><li>显示：触发显示提示的事件</li></ul><p><strong>属性：</strong></p><ul><li>内容：提示文字内容</li></ul><p><strong>说明：</strong> 触发后会以弹窗形式显示提示信息。</p><h3 id="确认框" tabindex="-1">确认框 <a class="header-anchor" href="#确认框" aria-label="Permalink to “确认框”">​</a></h3><p>弹出确认对话框，用户可以选择确认或取消。</p><p><strong>输入：</strong></p><ul><li>msg：要显示的确认内容（可通过属性设置）</li><li>显示：触发显示确认框的事件</li></ul><p><strong>输出：</strong></p><ul><li>确认：用户点击确认时触发</li><li>取消：用户点击取消时触发</li></ul><p><strong>属性：</strong></p><ul><li>Text：确认框的提示文字</li></ul><p><strong>说明：</strong> 触发后会显示确认对话框，根据用户的选择触发不同的输出事件。</p><h3 id="触摸提示" tabindex="-1">触摸提示 <a class="header-anchor" href="#触摸提示" aria-label="Permalink to “触摸提示”">​</a></h3><p>播放一个触摸提示的动画，引导用户进行交互。</p><p><strong>输入：</strong></p><ul><li>物体：要显示提示的物体节点（通常是手指动画）</li><li>显示：触发显示提示的事件</li><li>关闭：触发关闭提示的事件</li></ul><p><strong>输出：</strong></p><ul><li>结束：提示动画结束时触发</li></ul><p><strong>属性：</strong></p><ul><li>类型：选择提示动画类型 <ul><li>单次点击：播放一次点击动画</li><li>快速点击：播放快速点击动画</li><li>拖拽：从当前位置拖拽到目标位置</li><li>上下滑动：上下滑动动画</li><li>左右滑动：左右滑动动画</li><li>转圈：转圈动画</li><li>长按：长按动画</li></ul></li><li>大小：提示动画的缩放大小</li><li>拖拽终点-x/y：拖拽动画的目标位置（仅拖拽类型）</li><li>长度或半径：滑动或转圈的距离/半径</li><li>速度：动画的移动速度</li></ul><p><strong>说明：</strong></p><ul><li>可以点击&quot;创建触摸动画&quot;自动创建手指动画物体</li><li>可以点击&quot;预览效果&quot;预览提示动画</li><li>节点启动时默认关闭提示</li></ul><h3 id="输出控制台" tabindex="-1">输出控制台 <a class="header-anchor" href="#输出控制台" aria-label="Permalink to “输出控制台”">​</a></h3><p>将内容打印到浏览器控制台，用于调试。</p><p><strong>输入：</strong></p><ul><li>msg：要打印的内容（可通过属性设置）</li><li>log：以log级别打印</li><li>warn：以warn级别打印</li><li>error：以error级别打印</li></ul><p><strong>属性：</strong></p><ul><li>msg：要打印的内容</li></ul><p><strong>说明：</strong></p><ul><li>可以通过不同的输入接口选择不同的日志级别</li><li>输入值会显示在输入接口的标签上</li></ul><h2 id="游戏控制" tabindex="-1">游戏控制 <a class="header-anchor" href="#游戏控制" aria-label="Permalink to “游戏控制”">​</a></h2><h3 id="重新开始" tabindex="-1">重新开始 <a class="header-anchor" href="#重新开始" aria-label="Permalink to “重新开始”">​</a></h3><p>重新开始游戏流程，重置当前分镜。</p><p><strong>输入：</strong></p><ul><li>重启：触发重新开始的事件</li></ul><p><strong>说明：</strong> 触发后会停止当前蓝图，然后重新启动。</p><h3 id="切换页面" tabindex="-1">切换页面 <a class="header-anchor" href="#切换页面" aria-label="Permalink to “切换页面”">​</a></h3><p>切换到新的页面（分镜）。</p><p><strong>输入：</strong></p><ul><li>切换：触发切换页面的事件</li></ul><p><strong>属性：</strong></p><ul><li>页码：目标页面的页码（从1开始）</li><li>页面名称：目标页面的名称</li></ul><p><strong>说明：</strong> 触发后会停止当前蓝图，然后加载并启动指定的页面。</p><h3 id="页面结束" tabindex="-1">页面结束 <a class="header-anchor" href="#页面结束" aria-label="Permalink to “页面结束”">​</a></h3><p>标记当前页面阅读结束。</p><p><strong>输入：</strong></p><ul><li>结束：触发页面结束的事件</li></ul><p><strong>说明：</strong> 触发后会通知应用当前页面已结束，通常用于绘本翻页逻辑。</p><h3 id="通知绘本操作" tabindex="-1">通知绘本操作 <a class="header-anchor" href="#通知绘本操作" aria-label="Permalink to “通知绘本操作”">​</a></h3><p>操作绘本相关事件，与绘本应用交互。</p><p><strong>输入：</strong></p><ul><li>触发：触发操作的事件</li><li>param：附加的参数信息</li></ul><p><strong>属性：</strong></p><ul><li>事件：选择要触发的事件类型 <ul><li>隐藏底部字幕：隐藏页面底部的字幕</li></ul></li><li>附加信息：附加的参数信息</li></ul><p><strong>说明：</strong> 用于与绘本应用进行交互，触发应用层面的操作。</p><h2 id="时间控制" tabindex="-1">时间控制 <a class="header-anchor" href="#时间控制" aria-label="Permalink to “时间控制”">​</a></h2><h3 id="停止时间" tabindex="-1">停止时间 <a class="header-anchor" href="#停止时间" aria-label="Permalink to “停止时间”">​</a></h3><p>暂停或恢复游戏时间，暂停所有时间相关的动画和逻辑。</p><p><strong>输入：</strong></p><ul><li>停止：触发暂停的事件</li><li>恢复：触发恢复的事件</li></ul><p><strong>说明：</strong></p><ul><li>停止：暂停当前蓝图，所有时间相关的逻辑都会暂停</li><li>恢复：恢复当前蓝图，继续执行逻辑</li></ul><h3 id="时间缩放" tabindex="-1">时间缩放 <a class="header-anchor" href="#时间缩放" aria-label="Permalink to “时间缩放”">​</a></h3><p>加速或减慢时间效果，影响所有时间相关的动画和逻辑。</p><p><strong>输入：</strong></p><ul><li>scale：时间缩放倍数（可通过属性设置）</li><li>修改：触发修改时间缩放的事件</li></ul><p><strong>属性：</strong></p><ul><li>缩放倍数：时间缩放的比例（0-10，1为正常速度）</li></ul><p><strong>说明：</strong></p><ul><li>缩放倍数大于1时，时间变快</li><li>缩放倍数小于1时，时间变慢</li><li>会影响所有动画、延迟、间隔等时间相关的节点</li></ul><h2 id="脚本组件" tabindex="-1">脚本组件 <a class="header-anchor" href="#脚本组件" aria-label="Permalink to “脚本组件”">​</a></h2><p>自定义脚本组件，用于扩展功能。</p><p><strong>说明：</strong> 可以通过脚本组件实现自定义的逻辑和功能。</p><h2 id="屏蔽触摸" tabindex="-1">屏蔽触摸 <a class="header-anchor" href="#屏蔽触摸" aria-label="Permalink to “屏蔽触摸”">​</a></h2><p>屏蔽触摸事件，防止用户误操作。</p><p><strong>输入：</strong></p><ul><li>开启：触发开启屏蔽的事件</li><li>关闭：触发关闭屏蔽的事件</li></ul><p><strong>说明：</strong></p><ul><li>开启后，所有触摸事件都会被屏蔽</li><li>关闭后，恢复正常触摸响应</li><li>节点停止时会自动关闭屏蔽</li></ul><p><img src="'+e+'" alt="soundnode image"> 此节点用于播放音频，当选择音轨为无时，其他音频播放时，不会打断此音频播放，当选择某一个音轨时，其他对应音轨的音频节点播放讲打断此音频节点的播放。 如果需要为此音频添加字幕，可点击底部的<code>编辑字幕</code>按钮，在弹出的界面中可以手动添加字幕及卡点，也可以使用讯飞接口自动识别文本和时间点：</p><p><img src="'+o+'" alt="addmotionText image"></p><p>点击<code>自动识别</code>后，稍等片刻，上方会出现识别结果，如果字幕无需换行，可直接点击<code>生成字幕</code>按钮，如果需要换行，就点击对应换行位置的词语标签，即可生成多行字幕。</p><h2 id="文本转音频" tabindex="-1">文本转音频 <a class="header-anchor" href="#文本转音频" aria-label="Permalink to “文本转音频”">​</a></h2><p><img src="'+n+'" alt="textToSound image"></p><p>将文本转换为音频文件，需要开通讯飞文本转音频接口服务。</p><p><strong>属性：</strong></p><ul><li>文本：要转换的文本内容</li><li>命名：生成的音频文件名称</li><li>音色：选择语音音色 <ul><li>聆飞逸、聆小璇、聆小玥、聆玉昭、聆玉言、动漫少女</li></ul></li><li>语速：语音播放速度（0-100）</li><li>音量：语音音量大小（0-100）</li><li>语调：语音语调高低（0-100）</li><li>背景音：是否添加背景音</li></ul><p><strong>说明：</strong></p><ul><li>点击&quot;生成音频&quot;按钮后，会调用讯飞接口生成音频</li><li>生成的音频会自动上传到云端</li><li>需要先在系统设置中配置讯飞的AppID、ApiSecret和ApiKey</li><li>此功能需要开通<a href="https://www.xfyun.cn/services/smart-tts" target="_blank" rel="noreferrer">讯飞文本转音频接口服务</a></li></ul><h2 id="振动" tabindex="-1">振动 <a class="header-anchor" href="#振动" aria-label="Permalink to “振动”">​</a></h2><p>调用设备振动功能，提供触觉反馈。</p><p><strong>输入：</strong></p><ul><li>震动：触发振动的事件</li></ul><p><strong>属性：</strong></p><ul><li>振动强度：振动的强度（0-1） <ul><li>小于0.5：短振动</li><li>大于等于0.5：长振动</li></ul></li></ul><p><strong>说明：</strong> 仅在支持振动的设备上有效。</p><h2 id="自动点击" tabindex="-1">自动点击 <a class="header-anchor" href="#自动点击" aria-label="Permalink to “自动点击”">​</a></h2><p>自动执行录制好的点击操作，用于自动化测试或演示。</p><p><strong>属性：</strong></p><ul><li>是否激活：是否启用自动点击功能</li></ul><p><strong>说明：</strong></p><ul><li>需要在&quot;录制操作&quot;模式下运行蓝图并录制点击操作</li><li>启用后，运行蓝图时会自动执行录制好的点击序列</li><li>点击操作会按照录制时的时间顺序执行</li></ul><h2 id="保存自定义数据" tabindex="-1">保存自定义数据 <a class="header-anchor" href="#保存自定义数据" aria-label="Permalink to “保存自定义数据”">​</a></h2><p>保存自定义数据到本地或云端。</p><p><strong>说明：</strong> 用于保存游戏进度、用户数据等自定义信息。</p>',111)])])}const f=i(s,[["render",p]]);export{b as __pageData,f as default};
